const CATEGORY_GRADIENTS = {
  'Hot Wallet': 'from-primary-500 to-primary-700',
  'Hardware Wallet': 'from-slate-500 to-slate-800',
  'Exchange Wallet': 'from-gold to-gold-600',
  'Institutional/Multi-Sig': 'from-emerald-500 to-emerald-800',
}

/** Tailwind gradient classes for a wallet's icon tile. */
export const walletGradient = (wallet) =>
  BRAND_GRADIENTS[wallet?.id] || CATEGORY_GRADIENTS[wallet?.category] || 'from-primary-500 to-primary-700'

/** Single-letter monogram used on wallet icons/logos. */
export const walletInitial = (wallet) => (wallet?.name || 'W').trim().charAt(0).toUpperCase()

export const canInjectEVM = (wallet) => Array.isArray(wallet?.connectors) && wallet.connectors.includes('injectedEVM')

export const canInjectSolana = (wallet) =>
  Array.isArray(wallet?.connectors) && wallet.connectors.includes('injectedSolana')

/** localStorage key for the "recently used" wallets. */
export const RECENT_WALLETS_KEY = 'primewave_recent_wallets'

/** Recently connected wallet ids (most recent first, max 4). */
export const getRecentWalletIds = () => {
  try {
    const raw = JSON.parse(window.localStorage.getItem(RECENT_WALLETS_KEY) || '[]')
    return Array.isArray(raw) ? raw.map(String) : []
  } catch (e) {
    return []
  }
}

/** Record a wallet as recently used. */
export const recordRecentWallet = (walletId) => {
  try {
    const next = [walletId, ...getRecentWalletIds().filter((id) => id !== walletId)].slice(0, 4)
    window.localStorage.setItem(RECENT_WALLETS_KEY, JSON.stringify(next))
  } catch (e) {
    /* storage unavailable - non-critical */
  }
}
